Let \(\psi \colon C \to {\mathbb P}^1\) be a degree \(d\) morphism of smooth projective geometrically integral curves such that all points of \(C\) have ramification index at most \(2\) and let \(v\) be a nonarchimedean place of \(k\) with sufficiently large residue field.
    \begin{enumerate}
        \item For all partitions \((d_i)_{i=1}^r\vdash d\), there exists a \(t\in {\mathbb P}^1(k)\) such that \({\mathbf k}(C_t)\) is a field with \(r\) places \(w_i|v\), each of inertia degree \(f(w_i/v) = d_i\).
        \item For every \(t\in {\mathbb P}^1(k)\) outside the branch locus and every place \(w|v\) of \({\mathbf k}(C_t)\), the ramification degree \(e(w/v)\) is at most \(2.\) Furthermore, the number of ramified places is bounded above by 
        \(
             \#\{{\overline{x}} \in C_{{\overline{t}}} : e({\overline{x}/\overline{t}}) > 1\} 
        \) where \(\overline{t}\) is the specialization of \(t\).
        \item If \(\psi\) has a \(k_v\)-rational branch point and there is an odd degree ramification point \(x_v\in C\) lying above it, then for all quadratic ramified extensions \(L/{\mathbf k}(x_v)\), there exists a \(t\in {\mathbb P}^1(k)\) such that \({\mathbf k}(C_t)\otimes_k k_v\) contains \(L\) as a maximal subfield.
    \end{enumerate}

Let \(K\) be a nonarchimedean local field, let \(L/K\) be a totally tamely ramified degree \(e\) extension, let \(K\subset F\subset L\) be the maximal Galois subextension contained in \(L\). Then:
    \begin{enumerate}
        \item \(\mathrm{Gal}(F/K)\) is cyclic,
        \item \( [F:K] = \gcd\left(e, q_K - 1\right),\) and \item if \(L'/K\) is a totally tamely ramified degree \(e\) extension that contains \(F\), then \(L' = g(L)\) for some \(g\in \mathrm{Gal}(K^{tr}/K)\). \end{enumerate}

Consider the following map of exact sequences:
        \[
        \begin{tikzcd}
             0 \arrow[r] & {\dfrac{ R[\beta]\cap {\mathfrak m}_S}{{\mathfrak m}_R[\beta]}} 
             \arrow[r]\arrow[d] & 
             {\dfrac{R}{{\mathfrak m}_R}[\beta \bmod {\mathfrak m}_R]} 
             \arrow[r]\arrow[d, hook] & \dfrac{R}{{\mathfrak m}_R}[\beta \bmod {\mathfrak m}_S] 
             \arrow[r]\arrow[d] 
            & 0\\
            0 \arrow[r] & \dfrac{{\mathfrak m}_S}{{\mathfrak m}_RS} \arrow[r] & \dfrac{S}{{\mathfrak m}_RS} \arrow[r] & \dfrac{S}{{\mathfrak m}_S} \arrow[r] & 0.
        \end{tikzcd}
    \]

Note that \(s\) depends only on \(f\) and \({\mathfrak p}_0\); it does not depend on \({\mathfrak p}_a\). Then we have
    \begin{equation} f - \tilde{f}^e = p_0s = (p - a\pi)s. 
    \end{equation}

Setting \(v := 1 + v(a)\) and \(u:= a\pi^{1-v} \in {\mathcal O}_K^{\times}\), the above equalities and congruences yield:
    \[
        h_1(z)\cdots h_r(z) \equiv f\bmod {\mathfrak p}_a = \tilde{f}^e - u\pi^{v} s = (z- \theta_1)^e\cdots (z - \theta_r)^e - u\pi^v s.
    \]
    Since for \(i\neq j\), \(h_i\equiv (z - \theta_i)^e\pmod \pi\) is relatively prime to \(h_j\equiv (z - \theta_j)^e\pmod \pi\) and \(h_i,h_j, (z-\theta_i)^e, (z-\theta_j)^e\) are all monic of degree \(e\), Lemma~\ref{lem:LiftingFactorizations} implies that \(h_i(z) \equiv (z - \theta_i)^e\pmod{\pi^v}\) for all \(i\). In particular, if we set \(\theta := \theta_1\) and \(g(z):= h_1(z + \theta_1)\), then \(g(z) \equiv z^e\bmod \pi^v\) in \(R/{\mathfrak p}_a[\theta, z] \simeq{\mathcal O}_{K'}[z]\).  Furthermore, by \eqref{eq:fmodulop}
    \begin{equation}
        g(0) = (f\bmod{\mathfrak p}_a)(\theta)\prod_{i=2}^rh_i(\theta)^{-1} = -u\pi^vs(\theta)\prod_{i=2}^rh_i(\theta)^{-1} 
        \equiv -u\pi^vs(\theta)\prod_{i=2}^r(\theta - \theta_i)^{-e}\bmod \pi^{v+1} \end{equation}
    Since \(s\in R[z]\) gives a unit in \(S\), \(s(\theta)\in {\mathcal O}_{K'}^{\times}\). Thus, the Newton polygon of \(g\) has a single segment of slope \(-\frac{v}{e}\), which gives the desired lower bound in~\eqref{part:Ramification}.

Furthermore, by \eqref{eq:fmodulop}
    \begin{equation}
        g(0) = (f\bmod{\mathfrak p}_a)(\theta)\prod_{i=2}^rh_i(\theta)^{-1} = -u\pi^vs(\theta)\prod_{i=2}^rh_i(\theta)^{-1} 
        \equiv -u\pi^vs(\theta)\prod_{i=2}^r(\theta - \theta_i)^{-e}\bmod \pi^{v+1} \end{equation}

Moreover, for a fixed \(a_0\in {\mathcal O}_K^{\times}\),
    \begin{align*}
        \mu_{{\mathcal O}_K}\left(\left\{a\in {\mathcal O}_K^{\times} : \;{\mathbf k}(S_{{\mathfrak p}_a})\simeq {\mathbf k}(S_{{\mathfrak p}_{a_0}}) \right\}\right) & =  \mu_{{\mathcal O}_K}\left(\left\{a\in {\mathcal O}_K^{\times} : aa_0^{-1}\in {\mathcal O}_{K'}^{\times e} \right\}\right) \\& = \mu_{{\mathcal O}_K}({\mathcal O}_K^{\times})\mu_{{\mathcal O}_K^{\times}}\left(a_0 ({\mathcal O}_K^{\times}\cap{\mathcal O}_{K'}^{\times e}) \right)\\
        & = \mu_{{\mathcal O}_K}({\mathcal O}_K^{\times})\mu_{{\mathcal O}_K^{\times}}\left({\mathcal O}_K^{\times}\cap{\mathcal O}_{K'}^{\times e} \right)\\
        & = \frac{q_K-1}{q_K}\cdot\frac1{[{\mathcal O}_K^{\times} : {\mathcal O}_K^{\times}\cap {\mathcal O}_{K'}^{\times e}]}.
    \end{align*}

To prove the rest of~\eqref{part:RamIsom} it remains to prove the following statements:
    \begin{enumerate}
        \item[\eqref{part:Existence}] If \(\tilde{u}\in H\) generates \(H/{\mathcal O}_{K}^{\times}{\mathcal O}_{K'}^{\times e}\), then there exists a \(u\in {\mathcal O}_K^{\times}\) and \(v\in \mathbb{N}\) such that \(\left(-u s(\theta)\right)^{m_{v}}\tilde{u}^{-1}\in {\mathcal O}_{K'}^{\times e}\).

        \item[\eqref{part:Uniqueness}] If \(u\in {\mathcal O}_K^{\times}\) and \(v\in \mathbb{N}\), then \(\langle\left(-us(\theta)\right)^{m_v}\rangle\) generates \(H/{\mathcal O}_{K}^{\times}{\mathcal O}_{K'}^{\times e}\).
    \end{enumerate}

We say that the morphism \(\psi\) has \defi{good reduction} if:
    \begin{enumerate}
        \item There exist smooth proper \({\mathcal O}_K\)-schemes \({\mathcal C}, {\mathcal D}\) whose generic fibers \({\mathcal C}_K, {\mathcal D}_K\) are isomorphic to \(C, D\), respectively, \item There exists a finite surjective
        morphism \(\Psi\colon {\mathcal C} \to {\mathcal D}\) such that \(\Psi_{K}=\psi\), and \item There exists a minimal reduced closed codimension \(1\) subscheme \({\mathcal Z}\subset {\mathcal C}\) such that \(\Psi|_{{\mathcal C}\smallsetminus {\mathcal Z}}\colon {\mathcal C}\smallsetminus {\mathcal Z} \to {\mathcal D}\) is \'etale, and for this minimal subscheme, the maps \({\mathcal Z} \to \Psi({\mathcal Z})\) and \(\Psi({\mathcal Z}) \to \mathrm{Spec} {\mathcal O}_K\) are both \'etale. \end{enumerate}

Let \(\psi\colon C \to D\) be a morphism of good reduction,  let \(\Psi\colon{\mathcal C}\to {\mathcal D}\) be the associated integral model, and let \(\psi_0\colon C_0 \to D_0\) denote the restriction of \(\Psi\) to the special fiber. Let \(\overline{x}\in {\mathcal C}\) be a closed point and let \(\overline{t} := \Psi(\overline{x})\). We have the following properties.
        \begin{enumerate}
            \item The ring map \(R := {\mathcal O}_{{\mathcal D}, \overline{t}}\hookrightarrow S := {\mathcal O}_{{\mathcal C}, \overline{x}}\) is a finite extension of regular local rings.
            \item If \(e(\overline{x}/\overline{t})=1\), then \(R\hookrightarrow S\) is \'etale.
            \item If \(e(\overline{x}/\overline{t})>1\), then there exists a unique height \(1\) prime ideal \({\mathfrak p}_0\subset R\) such that \(R\to S\) is \'etale at all primes \({\mathfrak q}\subset S\) such that \({\mathfrak q}\cap R\) does not contain \({\mathfrak p}_0\). Furthermore, for this prime \({\mathfrak p}_0\):
            \begin{enumerate}
                \item there is a unique prime \({\mathfrak q}_0\subset S\) lying over \({\mathfrak p}_0\), \item the ring maps \(R/{\mathfrak p}_0 \to S/{\mathfrak q}_0\) and \({\mathcal O}_K\to R/{\mathfrak p}_0\) are both \'etale and \([R/{\mathfrak p}_0:{\mathcal O}_K] = \deg(\overline{t})\). \end{enumerate}
            In other words, there is a unique codimension \(1\) point \(x\in {\mathcal C}\) that specializes to \(\overline{x}\) where \(\Psi\) is ramified and, for this point,
            \[
            e(x/\psi(x)) = e(\overline{x}/\overline{t})\quad \textup{and}\quad\deg(x) = \deg(\overline{x}).
            \]
        \end{enumerate}

By Definition~\ref{def:GoodReductionOfCurves}\eqref{gr:flatmorphism}, \(S\) is a flat \(R\)-module (see, e.g.,~\cite{QingLiu}*{Chapter 4, Remark 3.11}), hence free. Thus,
        \begin{align*}
            [S/{\mathfrak m}_S:R/{\mathfrak m}_R]e({\mathfrak m}_S/{\mathfrak m}_R) & = \dim_{R/{\mathfrak m}_R}S/{\mathfrak m}_R S = \mathrm{rank}_R S = \dim_{{\mathbf k}(R_{{\mathfrak p}_0})}S_{{\mathfrak p}_0}/{\mathfrak p}_0 S_{{\mathfrak p}_0}\\
            & = \sum_{{\mathfrak q} |{\mathfrak p}_0} \dim_{{\mathbf k}(R_{{\mathfrak p}_0})}S_{{\mathfrak q}}/{\mathfrak p}_0 S_{{\mathfrak q}}
            = \sum_{{\mathfrak q}|{\mathfrak p}_0}[S_{{\mathfrak q}}/{\mathfrak q}:R_{{\mathfrak p}_0}/{\mathfrak p}_0]e({\mathfrak q} S_{{\mathfrak q}}/{\mathfrak p}_0R_{{\mathfrak p}_0}).
        \end{align*}

Furthermore, we have the following equalities: 
        \[
            {\mathbf k}(S_{{\mathfrak p}})  = {\mathbf k}(C_t)_{\overline{x}},\;
            \deg(\overline{x}) = [S/{\mathfrak m}_S:R/{\mathfrak m}_R],\;
            e(\overline{x}/\overline{t}) = e({\mathfrak m}_S/{\mathfrak m}_R), \;\textup{and}\;
            v(t, {\mathcal B})  = 1 + v(a).
        \]
